// Typed project-graph IPC. Types come from Rust (`src/bindings`, generated by
// ts-rs). Rust owns graph identities, semantics, admission, and validation;
// the frontend reads bounded projections and proposes typed changes. Never
// bypass these wrappers with raw `invoke`.
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type { ApplyChangeRequest } from "../bindings/ApplyChangeRequest";
import type { ApplyOutcome } from "../bindings/ApplyOutcome";
import type { BackupInfo } from "../bindings/BackupInfo";
import type { ChangeProposal } from "../bindings/ChangeProposal";
import type { ChangeRequest } from "../bindings/ChangeRequest";
import type { EntityDetail } from "../bindings/EntityDetail";
import type { EntityId } from "../bindings/EntityId";
import type { GraphEvent } from "../bindings/GraphEvent";
import type { GraphQuery } from "../bindings/GraphQuery";
import type { GraphSnapshot } from "../bindings/GraphSnapshot";
import type { GraphStatus } from "../bindings/GraphStatus";
import type { GraphView } from "../bindings/GraphView";
import type { GraphViewInput } from "../bindings/GraphViewInput";
import type { GraphViewSummary } from "../bindings/GraphViewSummary";
import type { ImpactReport } from "../bindings/ImpactReport";
import type { ImpactRequest } from "../bindings/ImpactRequest";
import type { InspectAtSourceRequest } from "../bindings/InspectAtSourceRequest";
import type { MathOverview } from "../bindings/MathOverview";
import type { OperationRecord } from "../bindings/OperationRecord";
import type { ReconcileReport } from "../bindings/ReconcileReport";
import type { RecoveryOption } from "../bindings/RecoveryOption";
import type { SourceInspection } from "../bindings/SourceInspection";
import type { ViewId } from "../bindings/ViewId";
import type { Vocabulary } from "../bindings/Vocabulary";

export const graphCommands = {
  /** Where the project graph stands (attached, temporary, unavailable + recovery options). */
  status: () => invoke<GraphStatus>("graph_status"),
  /** The closed relation/entity vocabulary with endpoint rules (display only). */
  vocabulary: () => invoke<Vocabulary>("graph_vocabulary"),
  /** A bounded slice of the graph (check `truncated`). */
  snapshot: (query: GraphQuery) => invoke<GraphSnapshot>("graph_snapshot", { query }),
  entity: (entity: EntityId) => invoke<EntityDetail>("graph_entity", { entity }),
  /** Entities bound at a source position (unsaved overlays are labelled). */
  inspectAtSource: (request: InspectAtSourceRequest) =>
    invoke<SourceInspection>("graph_inspect_at_source", { request }),
  impact: (request: ImpactRequest) => invoke<ImpactReport>("graph_impact", { request }),
  mathOverview: () => invoke<MathOverview>("graph_math_overview"),
  /** Validate a typed change (attributed to the user); nothing is applied. */
  proposeChange: (request: ChangeRequest) => invoke<ChangeProposal>("graph_propose_change", { request }),
  /** Apply a valid proposal (re-validated; one transaction or an explicit conflict). */
  applyChange: (request: ApplyChangeRequest) => invoke<ApplyOutcome>("graph_apply_change", { request }),
  views: () => invoke<GraphViewSummary[]>("graph_views"),
  viewGet: (view: ViewId) => invoke<GraphView>("graph_view_get", { view }),
  /** Save positions/viewport/filters (presentation only; never changes relations). */
  viewSave: (view: GraphViewInput) => invoke<GraphView>("graph_view_save", { view }),
  viewDelete: (view: ViewId) => invoke<boolean>("graph_view_delete", { view }),
  recover: (option: RecoveryOption) => invoke<GraphStatus>("graph_recover", { option }),
  /** Interrupted cross-service operations that need reconciliation. */
  operations: () => invoke<OperationRecord[]>("graph_operations"),
  /**
   * "Reindex project": rebuild derived projections from the files (every file
   * re-read unless `force` is false). Never touches curated records.
   */
  reconcile: (force = true) => invoke<ReconcileReport>("graph_reconcile", { force }),
  /** Take a consistent backup of the project graph now. */
  backup: () => invoke<BackupInfo>("graph_backup"),
  /** Graph backups, newest first (restorable via `recover` when the graph is damaged). */
  backups: () => invoke<BackupInfo[]>("graph_backups"),
};

export const graphEvents = {
  /** Status changes, applied changes (delta + origin), reconciliation progress. */
  graph: (handler: (event: GraphEvent) => void): Promise<UnlistenFn> =>
    listen<GraphEvent>("graph:event", (e) => handler(e.payload)),
  /** The listener fell behind: re-read graph state. */
  graphResync: (handler: () => void): Promise<UnlistenFn> => listen("graph:resync", () => handler()),
};
